import base64
import logging
import os
import subprocess

ENGINE_B64 = ""

log = logging.getLogger("gamma_slider")


class LinuxBackend:
    def __init__(self, engine_path):
        self.engine_path = engine_path

    def unpack(self):
        if not ENGINE_B64:
            return
        try:
            bin_data = base64.b64decode(ENGINE_B64)
            if not os.path.exists(self.engine_path):
                parent = os.path.dirname(self.engine_path)
                if parent:
                    os.makedirs(parent, exist_ok=True)
                with open(self.engine_path, "wb") as f:
                    f.write(bin_data)
                os.chmod(self.engine_path, 0o755)
                log.info("Engine unpacked to %s", self.engine_path)
        except Exception as e:
            log.error("unpack_engine: %s", e)

    def apply(self, temp, gamma, mode=0, wait=False):
        if not os.path.exists(self.engine_path):
            log.warning("Engine not found: %s", self.engine_path)
            return False
        args = [self.engine_path, str(temp), str(gamma)]
        if mode != 0:
            args.append(str(mode))
        try:
            if wait:
                subprocess.run(
                    args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=False,
                )
            else:
                subprocess.Popen(args, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            log.debug("Engine: temp=%sK gamma=%s mode=%s", temp, gamma, mode)
            return True
        except Exception as e:
            log.error("apply_engine: %s", e)
            return False

    def reset(self, wait=False):
        return self.apply(6500, 1.0, 0, wait=wait)

    def close(self):
        self.reset(wait=True)
